from packaging.version import Version

def newest_compatible(versions: list[str], minimum: str) -> str | None:
    min_ver = Version(minimum)
    compatible_versions = [v for v in versions if Version(v) >= min_ver]
    if not compatible_versions:
        return None
    # Return the version string corresponding to the max Version object
    return max(compatible_versions, key=Version)

import asyncio
from typing import Any, Coroutine, List, Optional


def run_with_deadline(coros: List[Coroutine[Any, Any, Any]], seconds: float) -> List[Optional[Any]]:
    """
    Run the given coroutines concurrently, returning their results in input order.
    Any coroutine not finished within `seconds` is cancelled and its result is None.

    This function can be called repeatedly from synchronous code (no running event loop).
    """
    async def runner():
        tasks = [asyncio.create_task(coro) for coro in coros]
        done, pending = await asyncio.wait(tasks, timeout=seconds)
        # Cancel all pending tasks
        for task in pending:
            task.cancel()
        # Await cancellation completion
        for task in pending:
            try:
                await task
            except asyncio.CancelledError:
                pass
        # Prepare results in input order
        results = []
        for task in tasks:
            if task.done() and not task.cancelled():
                try:
                    results.append(task.result())
                except Exception:
                    # If a task raised, propagate the exception
                    raise
            else:
                results.append(None)
        return results

    return asyncio.run(runner())

